	@Test
	void anUnservedEdgeIsProbedInTheLmdbIndexOncePerParentLane() {
		RowState row = row(star(false));
		LmdbNativeCostVector quote = LmdbNativePackedFtreeQuote.quote(starPlan(row), row, Site.ROWS, 0L, 27_000D)
				.total();
		LmdbNativeCostVector scan = LmdbNativeCostVectors.pattern(edge(S, P1, A, 9_000D), row, 0L);
		LmdbNativeCostVector probe = LmdbNativeCostVectors.pattern(edge(S, P2, B, 9_000D), row, 1L << S);
		// the root scans its seed pattern (3000 distinct keys among 9000 rows); each edge probes once per root lane
		assertThat(quote.expected(Feature.INDEX_SEEK))
				.isEqualTo(scan.expected(Feature.INDEX_SEEK) + 2D * 3_000D * probe.expected(Feature.INDEX_SEEK));
		assertThat(quote.expected(Feature.DECODED_ROW))
				.isEqualTo(scan.expected(Feature.DECODED_ROW) + 2D * 3_000D * probe.expected(Feature.DECODED_ROW));
		assertThat(quote.expected(Feature.BATCH_ROW)).isEqualTo(21_000D);
		// every unserved lane opens a store cursor of its own
		assertThat(quote.expected(Feature.BRANCH_OPEN)).isEqualTo(2D * 3_000D);
	}

	@Test
	void aCycleClosingEdgeIsIntersectedPerPrimaryNeighbour() {
		StatsSource source = new StatsSource(100_000L).predicate(P, 3D, 3_000L)
				.predicateByObject(P, 3D, 3_000L)
				.adjacencyServed(true);
		RowState row = row(source);
		MultiJoinPlan join = new MultiJoinPlan(
				new PatternPlan[] { edge(S, P, A, 9_000D), edge(A, P, B, 9_000D), edge(B, P, S, 9_000D) },
				new MaskedFilter[0]);
		LmdbNativePackedFtree.Plan plan = LmdbNativePackedFtree.Planner.plan(join, row, new int[] { S, A, B });
		assertThat(plan).isNotNull();
		LmdbNativeCostVector quote = LmdbNativePackedFtreeQuote.quote(plan, row, Site.ROWS, 0L, 27D).total();
		// 3000 roots and 9000 second-level lanes; the closing edge binds once per second-level lane and the
		// intersection tests each of the 27000 third-level candidates, of which one in a thousand (3 / 3000) survives
		assertThat(quote.expected(Feature.INDEX_SEEK)).isEqualTo(3_000D + 9_000D + 9_000D);
		assertThat(quote.expected(Feature.MEMBERSHIP_TEST)).isEqualTo(27_000D);
		assertThat(quote.expected(Feature.BATCH_ROW)).isEqualTo(3_000D + 9_000D + 27D);
	}

